'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lesson,steps=[],position=0,timer=null,tab='principle',toastTimer;
let mastered=new Set();try{mastered=new Set(JSON.parse(localStorage.getItem('cs408-mastered')||'[]').filter(id=>LESSONS.some(l=>l.id===id)));}catch{}
const presets={};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2300);}
function renderNav(){const query=$('#search').value.trim().toLowerCase();$('#nav').innerHTML=GROUPS.map((g,i)=>{const rows=LESSONS.filter(l=>l.group===i&&`${l.title} ${l.en} ${l.id}`.toLowerCase().includes(query));return rows.length?`<div class="nav-group"><div class="nav-group-title"><b>${g.icon}</b>${g.name}</div>${rows.map(l=>`<button class="nav-item ${l.id===lesson?.id?'active':''}" data-lesson="${l.id}" ${l.id===lesson?.id?'aria-current="page"':''}><span class="nav-index">${String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span>${l.title}<span class="nav-done">${mastered.has(l.id)?'✓':''}</span></button>`).join('')}</div>`:'';}).join('')||'<p class="empty-search">没有找到知识点，试试“排序”或“TCP”。</p>';$('#progress-text').textContent=`${mastered.size} / ${LESSONS.length}`;$('#progress-fill').style.width=mastered.size/LESSONS.length*100+'%';}
function stop(){clearInterval(timer);timer=null;$('#play').textContent='▶ 自动演示';$('#play').setAttribute('aria-label','自动演示');}
function togglePlay(){if(timer){stop();return;}if(position===steps.length-1)position=0;renderStep();$('#play').textContent='Ⅱ 暂停演示';$('#play').setAttribute('aria-label','暂停演示');timer=setInterval(()=>{if(position<steps.length-1){position++;renderStep();}if(position===steps.length-1)stop();},Number($('#speed').value));}
function valuesFromForm(){return Object.fromEntries(new FormData($('#config')).entries());}
function loadData(){stop();try{const values=valuesFromForm();const next=buildSteps(lesson.id,values);steps=next;presets[lesson.id]=values;position=0;$('#input-error').textContent='';$('#timeline').max=steps.length-1;renderStep();return true;}catch(e){$('#input-error').textContent=e.message;return false;}}
function selectLesson(id){lesson=LESSONS.find(l=>l.id===id)||LESSONS.find(l=>l.id==='quick');stop();$('#breadcrumb').textContent=GROUPS[lesson.group].name;$('#eyebrow').textContent=`${GROUPS[lesson.group].en} / ${String(LESSONS.indexOf(lesson)+1).padStart(2,'0')}`;$('#title').innerHTML=`${lesson.title}<small>${lesson.en}</small>`;$('#subtitle').textContent=lesson.subtitle;document.title=`${lesson.title} · 408 实验室`;$('#facts').innerHTML=lesson.facts.map((v,i)=>`<div class="fact"><span class="fact-icon">${['◷','▧','≋','⌑'][i]}</span><div><small>${lesson.labels[i]}</small><strong>${v}</strong></div></div>`).join('');
 const preset=presets[lesson.id]||{};$('#config').innerHTML=lesson.fields.map(f=>`<div class="field ${f.wide?'wide':''}"><label for="field-${f.key}">${f.label}</label>${f.options?`<select id="field-${f.key}" name="${f.key}">${f.options.map(([v,label])=>`<option value="${v}" ${String(preset[f.key]??f.value)===v?'selected':''}>${label}</option>`).join('')}</select>`:`<input autocomplete="off" id="field-${f.key}" name="${f.key}" type="${f.type||'text'}" ${f.type==='number'?'step="1"':''} value="${esc(preset[f.key]??f.value)}">`}</div>`).join('')+'<button type="submit" class="secondary">应用参数 ↵</button>';
 $('#thinking').textContent=lesson.think;$('#principle').innerHTML=`<h3>核心思想</h3><p>${lesson.intro}</p><div class="principle-grid"><div><h3>如何运行</h3><ul>${lesson.principles.map(p=>`<li>${p}</li>`).join('')}</ul></div><div><h3>408 高频考点</h3><ul>${lesson.exams.map(p=>`<li>${p}</li>`).join('')}</ul></div></div><div class="exam-note">${lesson.note}</div>`;
 $('#code-language').textContent=lesson.language;$('#connection-intro').textContent=lesson.connection;$('#connections').innerHTML=lesson.links.map(id=>`<button class="related" data-lesson="${id}">${LESSONS.find(l=>l.id===id).title}<span>↗</span></button>`).join('');renderQuiz();renderNav();renderMark();loadData();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
}
function renderMark(){$('#mark').textContent=mastered.has(lesson.id)?'✓ 已掌握':'☆ 标记已掌握';$('#mark').classList.toggle('marked',mastered.has(lesson.id));$('#mark').setAttribute('aria-pressed',String(mastered.has(lesson.id)));}
function renderQuiz(){const q=lesson.quiz;$('#quiz').innerHTML=`<h3>${q.q}</h3>${q.options.map((v,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)}. ${v}</button>`).join('')}<div class="quiz-feedback" role="status"></div>`;}
function codeLines(line){$('#code-text').innerHTML=lesson.code.split('\n').map((s,i)=>`<span class="code-line ${i+1===line?'highlight':''}"><span class="line-number">${i+1}</span>${esc(s)||' '}</span>`).join('');}
function renderStep(){const s=steps[position];if(!s)return;$('#step-title').textContent=s.title;$('#step-description').textContent=s.description;$('#step-counter').textContent=`${position+1} / ${steps.length}`;$('#variables').innerHTML=Object.entries(s.vars).map(([k,v])=>`<span class="variable">${esc(k)} = ${esc(v)}</span>`).join('');$('#timeline').value=position;$('#timeline-text').textContent=`${String(position+1).padStart(2,'0')} / ${String(steps.length).padStart(2,'0')}`;$('#prev').disabled=position===0;$('#next').disabled=position===steps.length-1;$('#reset').disabled=position===0&&!timer;$('#scene-label').textContent=`${lesson.id.toUpperCase()} · ${position===steps.length-1?'COMPLETE':position===0?'READY':'RUNNING'}`;$('#visual').innerHTML=draw(s);$('#scene-caption').textContent=caption(s);codeLines(s.line);}
function cls(s,i){return (s.done||[]).includes(i)?'done':i===s.pivot?'pivot':(s.active||[]).includes(i)?'active':s.lo!==undefined&&(i<s.lo||i>s.hi)?'muted':'';}
function cells(a,active=[],labels=true){return a.map((x,i)=>`<div class="cell ${x===null?'empty':''} ${active.includes(i)?'active':''}">${x===null?'·':esc(x)}${labels?`<span class="cell-label">${i}</span>`:''}</div>`).join('');}
function draw(s){
 if(s.kind==='bars'){const max=Math.max(...s.a.map(Math.abs),1);return `<div class="bars">${s.a.map((x,i)=>`<div class="bar-column"><div class="bar ${cls(s,i)}" style="height:${32+Math.abs(x)/max*125}px">${x}</div><span class="bar-index">${i}</span>${i===s.pivot?'<span class="pointer">pivot</span>':''}</div>`).join('')}</div>`;}
 if(s.kind==='array'){return `<div class="array-row">${Array.from({length:s.slots},(_,i)=>`<div class="cell ${i>=s.a.length?'empty':''} ${s.active.includes(i)?'active':''}">${s.a[i]??'·'}<span class="cell-label">${i}</span></div>`).join('')}</div><div class="metric-row"><span>逻辑长度 length = ${s.n}</span><span>下标从 0 开始</span></div>`;}
 if(s.kind==='stack'){return `<div class="stack-wrap"><div class="stack">${s.a.length?s.a.map((x,i)=>`<div class="cell ${i===s.active?'active':''}" style="height:${Math.min(29,145/s.a.length)}px;min-height:${Math.min(29,145/s.a.length)}px">${x}${i===s.active?'<span style="position:absolute;right:-55px;font-size:10px">← top</span>':''}</div>`).join(''):'<span style="color:#a4b5a9;text-align:center">空栈</span>'}</div><div class="stack-caption">top = ${s.a.length-1}<br>已出栈<br><b>${s.removed.join(' → ')||'—'}</b></div></div>`;}
 if(s.kind==='queue'){return `<div class="array-row">${s.a.map((x,i)=>`<div class="cell ${x===null?'empty':''} ${s.active.includes(i)?'active':''}">${x??'·'}<span class="cell-label">${i}${i===s.front?'<br>↑ front':''}${i===s.rear?'<br>↑ rear':''}</span></div>`).join('')}</div><div class="metric-row" style="margin-top:26px">↶ next = (index + 1) mod 5</div><div class="metric-row">已出队：${s.removed.join(' → ')||'—'}</div>`;}
 if(s.kind==='graph')return graph(s);
 if(s.kind==='cache'){return `<div class="metric-row">访问：${s.index<0?'—':s.data[s.index]}　 ${s.hit===true?'✓ 命中':s.hit===false?'↻ 不命中':'比较有效位与标记'}</div><table class="matrix"><thead><tr><th>Cache 行</th><th>有效位</th><th>标记 Tag</th><th>主存块</th></tr></thead><tbody>${s.lines.map((l,i)=>`<tr><th>Line ${i}</th><td class="${s.active===i?'active':''}">${l.block===null?0:1}</td><td class="${s.active===i?'active':''}">${l.tag??'—'}</td><td class="${s.active===i?(s.hit===true?'done':'active'):''}">${l.block===null?'空':'Block '+l.block}</td></tr>`).join('')}</tbody></table>`;}
 if(s.kind==='pipeline'){const names=['IF','ID','EX','MEM','WB'];return `<div class="matrix-wrap"><table class="matrix"><thead><tr><th>指令 / 周期</th>${Array.from({length:s.n+4},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${Array.from({length:s.n},(_,r)=>`<tr><th>I${r+1}</th>${Array.from({length:s.n+4},(_,c)=>{const phase=c-r,valid=phase>=0&&phase<5&&c<s.cycle;return `<td class="${valid?(c===s.cycle-1?'active':'done'):'empty'}">${valid?names[phase]:'·'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
 if(s.kind==='lru'){return `<div class="array-row">${s.frames.map((x,i)=>`<div class="cell ${x===null?'empty':''} ${s.active===i?'active':''}">${x??'·'}<span class="cell-label">页框 ${i}</span></div>`).join('')}</div><div class="matrix-wrap"><table class="matrix"><thead><tr><th>访问</th>${s.data.map((n,i)=>`<th style="color:${i===s.index?'#af7d35':'inherit'}">${n}</th>`).join('')}</tr></thead><tbody>${s.frames.map((_,r)=>`<tr><th>框 ${r}</th>${s.data.map((_,c)=>`<td class="${c>s.index?'empty':s.history[c]?.slot===r?'active':''}">${s.history[c]?.frames[r]??'·'}</td>`).join('')}</tr>`).join('')}<tr><th>结果</th>${s.data.map((_,i)=>`<td class="${s.history[i]?.hit?'done':''}">${s.history[i]?(s.history[i].hit?'✓':'缺'):'·'}</td>`).join('')}</tr></tbody></table></div>`;}
 if(s.kind==='rr'){return `<div class="metric-row">${s.remaining.map((n,i)=>`<span class="metric-chip" style="${i===s.active?'border-color:#d4ad6b':''}">P${i+1} · 剩余 ${n}${s.finish[i]!==null?' ✓':''}</span>`).join('')}</div><div class="gantt">${s.gantt.length?s.gantt.map((g,i)=>`<div class="gantt-block ${i===s.gantt.length-1?'active':''}" style="flex-grow:${g.end-g.start}">P${g.p+1}<small>${g.start}</small></div>`).join('')+`<span style="font:10px Consolas;color:#91a391">${s.clock}</span>`:'<span style="color:#9eafa3;font-size:12px">CPU 等待分配 · 时间从 0 开始</span>'}</div><div class="metric-row">完成时间：${s.finish.map((t,i)=>`P${i+1} = ${t??'—'}`).join('　')}</div>`;}
 if(s.kind==='tcp')return tcp(s);
 return '';
}
function graph(s){const xy=[[55,100],[165,35],[165,170],[305,35],[305,170],[415,100]];let lines=EDGES.map(([a,b,w])=>{const done=s.parents[a]===b||s.parents[b]===a;const [x1,y1]=xy[a],[x2,y2]=xy[b];return `<line class="edge ${done?'done':''}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>${s.weighted?`<rect x="${(x1+x2)/2-8}" y="${(y1+y2)/2-9}" width="18" height="16" rx="4" fill="#f7faf8"/><text x="${(x1+x2)/2+1}" y="${(y1+y2)/2+3}" text-anchor="middle">${w}</text>`:''}`;}).join('');return `<svg class="diagram" role="img" aria-label="${s.weighted?'带权图与最短距离':'广度优先搜索图'}" viewBox="0 0 470 215">${lines}${xy.map(([x,y],i)=>`<circle class="${i===s.active?'active':s.done.includes(i)?'done':''}" cx="${x}" cy="${y}" r="19"/><text x="${x}" y="${y+4}" text-anchor="middle">${letter(i)}</text>${s.weighted?`<text x="${x}" y="${y+35}" text-anchor="middle">d=${s.dist[i]===1000000?'∞':s.dist[i]}</text>`:(s.seen||[]).includes(i)&&!s.done.includes(i)?`<text x="${x}" y="${y+34}" text-anchor="middle">队列中</text>`:''}`).join('')}</svg>`;}
function tcp(s){const messages=[`SYN · seq=${s.x}`,`SYN + ACK · seq=${s.y}, ack=${s.nextX}`,`ACK · seq=${s.nextX}, ack=${s.nextY}`];return `<svg class="diagram" role="img" aria-label="TCP 三次握手时序图" viewBox="0 0 500 235"><defs><marker id="arrowhead" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7" fill="#58997c"/></marker></defs><text x="70" y="19" text-anchor="middle">客户端</text><text x="430" y="19" text-anchor="middle">服务端</text><text class="tcp-status" x="70" y="38" text-anchor="middle">${s.client}</text><text class="tcp-status" x="430" y="38" text-anchor="middle">${s.server}</text><line x1="70" y1="50" x2="70" y2="225" stroke="#c8d9cd" stroke-dasharray="4 5"/><line x1="430" y1="50" x2="430" y2="225" stroke="#c8d9cd" stroke-dasharray="4 5"/>${messages.map((msg,i)=>s.phase>i?`<text x="250" y="${68+i*55}" text-anchor="middle" style="font-size:11px">${msg}</text><line x1="${i===1?426:74}" y1="${79+i*55}" x2="${i===1?74:426}" y2="${95+i*55}" stroke="${s.phase===i+1?'#c69b52':'#58997c'}" stroke-width="2" marker-end="url(#arrowhead)"/>`:'').join('')}</svg>`;}
function caption(s){const captions={bars:'下标显示在元素下方 · 柱高表示数值绝对值，比较依据元素实际数值',array:'连续存储 · 空心槽位表示可用空间，复制移动期间可能出现重复值',stack:'只在栈顶操作 · 后进先出 LIFO',queue:'牺牲一个槽位 · 最大容量为 4',graph:s.weighted?'边上的数字为权值 · d 为源点到该顶点的当前距离':'固定无向图 · 按字母顺序处理邻接点',cache:'直接映射 · 行号 = 主存块号 mod 4',pipeline:'IF 取指 → ID 译码 → EX 执行 → MEM 访存 → WB 写回',lru:'✓ 命中　缺 缺页 · 黄色格表示本次访问的页框',rr:'横轴为累计运行时间 · 时间片切换开销为 0',tcp:'时间从上向下推进 · 箭头表示报文传输方向'};return captions[s.kind]||'';}
function changeStep(n){stop();position=Math.max(0,Math.min(steps.length-1,n));renderStep();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-lesson]');if(nav){if(location.hash==='#'+nav.dataset.lesson)selectLesson(nav.dataset.lesson);else location.hash=nav.dataset.lesson;return;}const tabButton=e.target.closest('[data-tab]');if(tabButton){tab=tabButton.dataset.tab;$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tabButton)));$$('.tab-panel').forEach(p=>p.hidden=p.id!==tab);return;}const answer=e.target.closest('[data-answer]');if(answer){const chosen=Number(answer.dataset.answer),q=lesson.quiz;$$('.quiz-option').forEach((b,i)=>{b.classList.toggle('correct',i===q.answer);b.classList.toggle('wrong',i===chosen&&chosen!==q.answer);});$('.quiz-feedback').textContent=(chosen===q.answer?'✓ 回答正确。':'再想一步：')+q.why;}});
$('#config').addEventListener('submit',e=>{e.preventDefault();loadData();});
$('#config').addEventListener('input',()=>{stop();$('#input-error').textContent='参数已修改，点击“应用参数”重新生成实验。';});
$('#search').addEventListener('input',renderNav);$('#play').addEventListener('click',togglePlay);$('#next').addEventListener('click',()=>changeStep(position+1));$('#prev').addEventListener('click',()=>changeStep(position-1));$('#reset').addEventListener('click',()=>changeStep(0));$('#timeline').addEventListener('input',e=>changeStep(Number(e.target.value)));$('#speed').addEventListener('change',()=>{if(timer){stop();togglePlay();}});
$('#mark').addEventListener('click',()=>{if(mastered.has(lesson.id))mastered.delete(lesson.id);else mastered.add(lesson.id);try{localStorage.setItem('cs408-mastered',JSON.stringify([...mastered]));}catch{toast('当前浏览器不允许存储；本次会话仍可记录。');}renderMark();renderNav();});
$('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(lesson.code);toast('代码已复制');}catch{const t=document.createElement('textarea');t.value=lesson.code;document.body.append(t);t.select();const copied=document.execCommand('copy');t.remove();toast(copied?'代码已复制':'请选中代码后手动复制');}});
$('#random').addEventListener('click',()=>{const set=(k,v)=>{const el=$(`[name="${k}"]`);if(el)el.value=v;};const rand=(min,max)=>min+Math.floor(Math.random()*(max-min+1));switch(lesson.id){case 'quick':set('data',Array.from({length:7},()=>rand(1,90)).join(', '));break;case 'binary':{const a=Array.from({length:8},()=>rand(1,90)).sort((a,b)=>a-b);set('data',a.join(', '));set('target',a[rand(0,7)]);break;}case 'seq':set('data',Array.from({length:5},()=>rand(1,90)).join(', '));set('pos',rand(1,5));set('value',rand(1,90));break;case 'stack':set('data',Array.from({length:5},()=>rand(1,90)).join(', '));set('count',rand(1,5));break;case 'queue':set('data',Array.from({length:7},()=>rand(1,90)).join(', '));break;case 'cache':case 'lru':set('data',Array.from({length:10},()=>rand(0,7)).join(', '));break;case 'pipeline':set('count',rand(2,8));break;case 'rr':set('data',Array.from({length:3},()=>rand(2,9)).join(', '));set('quantum',rand(1,4));break;case 'tcp':set('x',rand(10,999));set('y',rand(10,999));break;case 'bfs':case 'dijkstra':set('start',letter(rand(0,5)));break;}loadData();toast('已生成新实验，可以开始演示');});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',e=>{if(window.innerWidth<=650&&!e.target.closest('#sidebar,#menu-toggle')){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>selectLesson(location.hash.slice(1)));document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,button')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key===' '){e.preventDefault();togglePlay();}if(e.key==='ArrowRight'){e.preventDefault();changeStep(position+1);}if(e.key==='ArrowLeft'){e.preventDefault();changeStep(position-1);}if(e.key==='/'){e.preventDefault();if(innerWidth<=650)$('#sidebar').classList.add('open');$('#search').focus();}if(e.key==='Escape')$('#sidebar').classList.remove('open');});
selectLesson(location.hash.slice(1)||'quick');
